<script setup lang="ts">
import { computed, ref } from 'vue'; import { ArrowRight, CalendarDays, Clock3, Search, UsersRound } from 'lucide-vue-next'; import LocationPicker from '@/components/LocationPicker.vue'; import EmptyState from '@/components/EmptyState.vue'; import ModalDialog from '@/components/ModalDialog.vue'; import { api } from '@/services/api'; import { errorMessage } from '@/services/http'; import type { Passenger, SeatAvailability, StationSuggestion, TrainSearchResult } from '@/types'
const today=new Date().toISOString().slice(0,10); const from=ref<StationSuggestion|null>(null); const to=ref<StationSuggestion|null>(null); const date=ref(today); const results=ref<TrainSearchResult[]>([]); const searched=ref(false); const loading=ref(false); const message=ref(''); const booking=ref<{train:TrainSearchResult;seat:SeatAvailability}|null>(null); const passengers=ref<Passenger[]>([]); const passengerId=ref(''); const submitting=ref(false)
const duration=(minutes:number|string)=>`${Math.floor(Number(minutes)/60)}时${Number(minutes)%60}分`; const time=(value:string)=>value?.slice(11,16)||'--:--'; const days=computed(()=>Array.from({length:5},(_,i)=>{const d=new Date();d.setDate(d.getDate()+i);return{value:d.toISOString().slice(0,10),label:i===0?'今天':`${d.getMonth()+1}/${d.getDate()}`}}))
async function search(){if(!from.value||!to.value){message.value='请从候选项中选择出发地和目的地';return} if(from.value.type===to.value.type&&from.value.value===to.value.value){message.value='出发地和目的地不能相同';return} message.value='';loading.value=true;try{results.value=await api.search({fromType:from.value.type,fromValue:from.value.value,toType:to.value.type,toValue:to.value.value,date:date.value});searched.value=true}catch(e){message.value=errorMessage(e)}finally{loading.value=false}}
async function openBooking(train:TrainSearchResult,seat:SeatAvailability){try{passengers.value=await api.passengers();passengerId.value=passengers.value[0]?.id||'';booking.value={train,seat}}catch(e){message.value=errorMessage(e)}}
async function create(){if(!booking.value||!passengerId.value)return;submitting.value=true;try{const t=booking.value.train;await api.createOrder({passengerId:passengerId.value,scheduleId:t.scheduleId,seatTypeCode:booking.value.seat.seatTypeCode,fromStopIndex:t.fromStopIndex,toStopIndex:t.toStopIndex,requestId:crypto.randomUUID()});booking.value=null;message.value='订单创建成功，请在 15 分钟内完成支付';await search()}catch(e){message.value=errorMessage(e)}finally{submitting.value=false}}
</script>
<template><div><section class="search-hero"><div class="container"><p class="eyebrow">轻松出发</p><h1>今天，想去哪里？</h1><div class="search-box"><LocationPicker v-model="from" placeholder="出发城市 / 车站"/><button class="swap" type="button" @click="[from,to]=[to,from]">⇄</button><LocationPicker v-model="to" placeholder="到达城市 / 车站"/><label class="date-field"><CalendarDays/><input v-model="date" type="date" :min="today"></label><button class="btn primary search-btn" @click="search"><Search/>{{loading?'查询中':'查询车票'}}</button></div><div class="quick-dates"><button v-for="d in days" :key="d.value" :class="{active:date===d.value}" @click="date=d.value">{{d.label}}</button></div></div></section><section class="container results-section"><div v-if="message" class="notice">{{message}}</div><header class="section-head"><div><h2>车次列表</h2><p>票价与余票信息实时更新</p></div><span v-if="searched">找到 {{results.length}} 个车次</span></header><div v-if="results.length" class="train-list"><article v-for="train in results" :key="train.scheduleId+train.fromStopIndex" class="train-card"><div class="train-id"><strong>{{train.trainNo}}</strong><span>{{train.trainName}}</span></div><div class="route-time"><div><strong>{{time(train.departureTime)}}</strong><span>{{train.fromStationName}}</span></div><div class="duration"><small>{{duration(train.durationMinutes)}}</small><i/><Clock3/></div><div class="arrival"><strong>{{time(train.arrivalTime)}}</strong><span>{{train.toStationName}}</span></div></div><div class="seats"><button v-for="seat in train.seats" :key="seat.seatTypeCode" :disabled="seat.available<=0" @click="openBooking(train,seat)"><span>{{seat.seatTypeName}}</span><strong>¥{{seat.price}}</strong><small>{{seat.available>0?`余 ${seat.available} 张`:'售罄'}}</small></button></div></article></div><EmptyState v-else-if="searched" title="没有符合条件的车次" hint="可以尝试更换车站或出行日期"/><div v-else class="search-placeholder"><Search/><p>选择出发地、目的地和日期后开始查询</p></div></section><ModalDialog :open="!!booking" title="确认购票信息" @close="booking=null"><div v-if="booking" class="booking-summary"><div class="booking-route"><strong>{{booking.train.fromStationName}}</strong><ArrowRight/><strong>{{booking.train.toStationName}}</strong></div><p>{{booking.train.trainNo}} · {{booking.train.travelDate}} · {{time(booking.train.departureTime)}} 出发</p><div class="price-line"><span>{{booking.seat.seatTypeName}}</span><strong>¥{{booking.seat.price}}</strong></div><label>选择乘车人<select v-model="passengerId"><option v-for="p in passengers" :key="p.id" :value="p.id">{{p.name}} · {{p.idNo}}</option></select></label><div v-if="!passengers.length" class="notice"><UsersRound/>请先到“乘车人”页面添加乘车人</div><button class="btn primary wide" :disabled="!passengerId||submitting" @click="create">{{submitting?'正在提交…':'提交订单'}}</button></div></ModalDialog></div></template>
